(async()=>{
 const r=window.__lastJackpot,scene=r.renderer.scene;
 const {HOTEL_RECTS}=await import('/lib/game/world.ts');
 const {Ray}=await import('/node_modules/@babylonjs/core/Culling/ray.js');
 const V=r.renderer.camera.position.constructor;
 const wall=HOTEL_RECTS.find(w=>w.id==='hotel-wall-1');
 const tx=Math.cos(wall.yaw),tz=Math.sin(wall.yaw),nx=-tz,nz=tx;
 const ray=(along,y,name)=>{const origin=new V(wall.x+tx*along+nx, y,wall.z+tz*along+nz);const hit=scene.pickWithRay(new Ray(origin,new V(-nx,0,-nz),1.3),m=>m.name===name);if(!hit?.hit)throw Error('Missing wall surface '+name);return 1-hit.distance;};
 const bare=ray(0,2,'hotel walls lime plaster architecture');
 const lowerCount=Math.round((wall.w-.03)/1.35),lowerWidth=(wall.w-.03)/lowerCount;
 const lowerAt=-wall.w/2+.015+lowerWidth*(Math.floor(lowerCount/2)+.5);
 const lower=ray(lowerAt,1.285,'hotel walls forest lacquer architecture');
 const upperCount=Math.round((wall.w-.03)/2.8),upperWidth=(wall.w-.03)/upperCount;
 const upperAt=-wall.w/2+.015+upperWidth*1.5;
 const upper=ray(upperAt,8.075,'hotel walls ivory molded plaster architecture');
 if(lower-bare<.04||upper-bare<.02)throw Error('Wall relief does not project far enough');
 const loaded=['stairs','ceiling','floor','details'].map(kind=>({kind,meshes:scene.meshes.filter(m=>m.name.startsWith('hotel-grand-'+kind)&&m.getTotalVertices()).length}));
 if(loaded.some(a=>a.meshes<1))throw Error('Missing Blender architecture');
 if(scene.meshes.some(m=>/hotel fitted stair carpet runner/.test(m.name)&&m.isEnabled()))throw Error('Old runner remains visible');
 return {wallReliefMetres:{backing:bare,lowerProjection:lower-bare,plasterProjection:upper-bare},loaded,totalVertices:scene.getTotalVertices()};
})()
